          <nav class="designer-tabs"><button type="button" :class="{active:tab==='design'}" @click="tab='design'">Diseno</button><button type="button" :class="{active:tab==='preview'}" @click="tab='preview'">Vista previa</button></nav>
          <div v-if="tab==='design'" class="stage-scroll">
            <div v-if="rows.length===0" class="designer-empty">Arrastra una plantilla o selecciona una opcion del panel izquierdo.</div>
            <article v-for="(row,rowIndex) in rows" :key="row.uid" class="designer-row" :class="{selected:selectedRowIndex===rowIndex}" draggable="true" @dragstart="startRowDrag($event,rowIndex)" @dragover.prevent @drop.stop="dropBefore($event,rowIndex)" @click="selectRow(rowIndex)">
