              <div v-if="row.antibiograma" class="antibiogram-block">Modulo antibiograma</div>
              <div v-else class="designer-columns">
                <button v-for="(column,columnIndex) in row.columns" :key="column.uid" type="button" class="designer-column" :class="{selected:selectedRowIndex===rowIndex&&selectedColumnIndex===columnIndex}" :style="columnStyle(column)" @click.stop="selectColumn(rowIndex,columnIndex)">
                  <small>{{ typeLabel(column.content.type) }}</small>
                  <strong v-if="column.content.type==='variable'">{{ column.content.value }}</strong>
                  <span v-else v-html="safeText(column.content.text)"></span>
