            </article>
          </div>
        </section>

        <aside v-show="!sideCollapsed && sideMode === 'settings'" class="designer-settings designer-side-panel"><nav class="side-panel-tabs"><button type="button" @click="sideMode='templates'">Plantillas</button><button type="button" class="active">Configuracion</button></nav>
          <div><p>Configuracion</p><h3>{{ settingsTitle }}</h3></div>
          <template v-if="selectedColumn">
