            <section class="rich-editor"><div class="rich-toolbar" role="toolbar" aria-label="Formato del contenido"><select :value="textSize" title="Tamano de letra" @change="setTextSize"><option value="small">Pequeno</option><option value="normal">Normal</option><option value="large">Grande</option><option value="huge">Muy grande</option></select><button type="button" title="Negrita" @mousedown.prevent="formatText('bold')"><strong>B</strong></button><button type="button" title="Cursiva" @mousedown.prevent="formatText('italic')"><em>I</em></button><button type="button" title="Subrayado" @mousedown.prevent="formatText('underline')"><u>U</u></button><button type="button" title="Subindice" @mousedown.prevent="formatText('subscript')">X<sub>2</sub></button><button type="button" title="Superindice" @mousedown.prevent="formatText('superscript')">X<sup>2</sup></button></div><div :key="editorKey" class="rich-content" contenteditable="true" role="textbox" aria-multiline="true" v-html="selectedColumn.content.text" @focus="rememberEditor" @input="captureText"></div></section>
            <BioNexusFormField label="Etiqueta" field-id="designer-label"><input id="designer-label" v-model="selectedColumn.content.value" class="bio-nexus-field" /></BioNexusFormField>
            <fieldset v-if="selectedColumn.content.type==='variable'" class="variable-modes"><legend>Tipo de variable</legend><label><input v-model="variableMode" type="radio" value="text" @change="applyVariableMode" />Texto</label><label><input v-model="variableMode" type="radio" value="numeric" @change="applyVariableMode" />Numerico</label><label><input v-model="variableMode" type="radio" value="formula" @change="applyVariableMode" />Formula</label><label><input v-model="variableMode" type="radio" value="autocompletion" @change="applyVariableMode" />Autocompletacion</label></fieldset>
            <BioNexusFormField v-if="selectedColumn.content.type==='variable' && variableMode==='formula'" label="Escriba la formula" field-id="designer-formula"><textarea id="designer-formula" v-model="selectedColumn.content.formula" class="bio-nexus-field" rows="2"></textarea></BioNexusFormField>
            <template v-if="selectedColumn.content.type==='variable' && (variableMode==='numeric' || variableMode==='formula')"><label class="designer-check"><input v-model="selectedColumn.content.allowDecimal" type="checkbox" @change="normalizeDecimals" /><span>Tiene decimales</span></label><BioNexusFormField label="Numero de decimales" field-id="designer-decimals"><input id="designer-decimals" v-model.number="selectedColumn.content.decimalLimit" class="bio-nexus-field" type="number" min="0" max="6" :disabled="!selectedColumn.content.allowDecimal" /></BioNexusFormField></template>
            <section v-if="selectedColumn.content.type==='variable' && variableMode==='autocompletion'" class="autocomplete-options"><strong>Lista de opciones</strong><div v-for="(option,index) in selectedColumn.content.autocompletionList" :key="index"><input v-model="option.text" class="bio-nexus-field" /><button type="button" @click="removeOption(index)"><BioNexusIcon name="delete" :size="17" /></button></div><button type="button" class="add-option" @click="addOption">Agregar</button></section>
            <div class="column-admin"><strong>Columna {{ selectedColumnIndex + 1 }} de {{ selectedRow.columns.length }}</strong><div><button type="button" :disabled="selectedColumnIndex===selectedRow.columns.length-1 || selectedColumn.span<=1" @click="resizeColumn(-1)">Reducir</button><span>{{ selectedColumn.span }}/12</span><button type="button" :disabled="selectedColumnIndex===selectedRow.columns.length-1 || selectedRow.columns[selectedColumnIndex+1].span<=1" @click="resizeColumn(1)">Ampliar</button></div><button type="button" :disabled="selectedRow.columns.length===1" @click="removeColumn">Eliminar columna</button></div>
            <BioNexusFormField label="Alineacion" field-id="designer-align"><select id="designer-align" v-model="selectedColumn.align" class="bio-nexus-field"><option value="left">Izquierda</option><option value="center">Centro</option><option value="right">Derecha</option></select></BioNexusFormField>
          </template>
          <template v-else-if="selectedRow">
            <BioNexusFormField label="Titulo de fila" field-id="designer-row-title"><input id="designer-row-title" v-model="selectedRow.rowTitle" class="bio-nexus-field" maxlength="60" /></BioNexusFormField>
            <div class="margin-grid"><BioNexusFormField v-for="side in marginSides" :key="side.key" :label="side.label" :field-id="'margin-'+side.key"><input :id="'margin-'+side.key" v-model.number="selectedRow.padding[side.key]" class="bio-nexus-field" type="number" min="0" max="60" /></BioNexusFormField></div>
            <label class="designer-check"><input v-model="selectedRow.antibiograma" type="checkbox" /><span>Modulo antibiograma</span></label>
          </template>
          <div v-else class="settings-empty">Selecciona una fila o una columna para configurarla.</div>
          <div class="designer-summary"><span>{{ rows.length }} fila(s)</span><span>{{ variableCount }} variable(s)</span></div>
        </aside>
      </main>
      <footer class="designer-footer"><div><strong>Los cambios son temporales.</strong><span>No se escribira format_vue durante esta validacion visual.</span></div><button type="button" class="bio-nexus-action bio-nexus-action-secondary" @click="requestClose">Cerrar</button><button type="button" class="bio-nexus-action bio-nexus-action-primary" disabled><BioNexusActionIcon action="save" />Guardar deshabilitado</button></footer>
    </section>
  </dialog>
</template>
<script setup>
