const selectedRow=computed(()=>rows.value[selectedRowIndex.value]??null);const selectedColumn=computed(()=>selectedRow.value?.columns?.[selectedColumnIndex.value]??null);const dirty=computed(()=>JSON.stringify(rows.value)!==original.value);const legacyOnly=computed(()=>!exam.value?.format_vue&&Boolean(exam.value?.format));const variableCount=computed(()=>rows.value.flatMap(row=>row.columns??[]).filter(column=>column.content.type==="variable").length);const settingsTitle=computed(()=>selectedColumn.value?"Contenido":selectedRow.value?"Fila":"Sin seleccion");
