function normalizeFormat(value){if(!value||!Array.isArray(value.rowContainer))return[];return value.rowContainer.map(row=>({uid:makeUid(),rowTitle:row.rowTitle??"",padding:{top:numberPx(row.style?.paddingTop),right:numberPx(row.style?.paddingRight),bottom:numberPx(row.style?.paddingBottom),left:numberPx(row.style?.paddingLeft)},antibiograma:Boolean(row.antibiograma),columns:Array.isArray(row.content?.stageColumns)?row.content.stageColumns.map(col=>({uid:makeUid(),span:Number(col.col)||1,align:["left","center","right"].includes(col.style?.textAlign)?col.style.textAlign:"left",content:normalizeContent(col.content?.[0])})):[]}))}
function normalizeContent(source={}){const type=source.type??"label";const text=source.text??(source.value?`<p>${source.value}</p>`:"");const value=source.value??plainText(text);return{type,text,value,numeric:Boolean(source.numeric),isFormula:Boolean(source.isFormula),formula:source.formula??"",allowDecimal:Boolean(source.allowDecimal),decimalLimit:Number(source.decimalLimit)||0,autocompletion:Boolean(source.autocompletion),autocompletionList:Array.isArray(source.autocompletionList)?JSON.parse(JSON.stringify(source.autocompletionList)):[]}}function plainText(html){const documentValue=new DOMParser().parseFromString(String(html??""),"text/html");return(documentValue.body.textContent??"").trim()}function numberPx(value){const number=parseInt(String(value??"0").replace("px",""),10);return Number.isFinite(number)?Math.max(0,number):0}
async function open(record){exam.value=record;rows.value=normalizeFormat(record?.format_vue);original.value=JSON.stringify(rows.value);selectedRowIndex.value=-1;selectedColumnIndex.value=-1;tab.value="design";sideMode.value="templates";dialog.value?.showModal();await nextTick()}
function addTemplate(key){rows.value.push(templateRow(key));selectRow(rows.value.length-1)}function startTemplateDrag(event,key){draggedTemplate.value=key;draggedRowIndex.value=-1;event.dataTransfer.effectAllowed="copy"}function startRowDrag(event,index){draggedRowIndex.value=index;draggedTemplate.value="";event.dataTransfer.effectAllowed="move"}function dropBefore(event,index){event.preventDefault();if(draggedTemplate.value){rows.value.splice(index,0,templateRow(draggedTemplate.value))}else if(draggedRowIndex.value>=0&&draggedRowIndex.value!==index){const[row]=rows.value.splice(draggedRowIndex.value,1);const target=draggedRowIndex.value<index?index-1:index;rows.value.splice(target,0,row)}resetDrag();renumberSelection()}function dropAtEnd(event){event.preventDefault();if(draggedTemplate.value)rows.value.push(templateRow(draggedTemplate.value));else if(draggedRowIndex.value>=0){const[row]=rows.value.splice(draggedRowIndex.value,1);rows.value.push(row)}resetDrag();renumberSelection()}function resetDrag(){draggedTemplate.value="";draggedRowIndex.value=-1}function renumberSelection(){selectedRowIndex.value=-1;selectedColumnIndex.value=-1}function selectRow(index){selectedRowIndex.value=index;selectedColumnIndex.value=-1;sideMode.value="settings";sideCollapsed.value=false}async function selectColumn(rowIndex,columnIndex){selectedRowIndex.value=rowIndex;selectedColumnIndex.value=columnIndex;sideMode.value="settings";sideCollapsed.value=false;await nextTick();syncEditor()}function moveRow(index,direction){const target=index+direction;if(target<0||target>=rows.value.length)return;const[row]=rows.value.splice(index,1);rows.value.splice(target,0,row);selectRow(target)}function duplicateRow(index){const copy=JSON.parse(JSON.stringify(rows.value[index]));copy.uid=makeUid();copy.columns.forEach(col=>{col.uid=makeUid();if(col.content.type==="variable"){const variable=nextVariable();col.content.value=variable;col.content.text=`<p>${variable}</p>`}});rows.value.splice(index+1,0,cop