selectedColumn.value.content.autocompletionList.push({text:"Nueva autocompletacion"})}function removeOption(index){selectedColumn.value.content.autocompletionList.splice(index,1)}function resizeColumn(direction){const row=selectedRow.value,index=selectedColumnIndex.value;if(!row||index>=row.columns.length-1)return;const current=row.columns[index],next=row.columns[index+1];if(direction<0&&current.span>1){current.span--;next.span++}if(direction>0&&next.span>1){current.span++;next.span--}}function removeColumn(){const row=selectedRow.value,index=selectedColumnIndex.value;if(!row||row.columns.length<=1)return;const removed=row.columns[index];const target=index>0?index-1:1;row.columns[target].span+=removed.span;row.columns.splice(index,1);selectedColumnIndex.value=Math.min(target,row.columns.length-1)}watch(selectedColumn,async()=>{await nextTick();syncEditor()});function safeText(value){return String(value??"").replace(/<script[\s\S]*?<\/script>/gi,"").replace(/\son\w+\s*=\s*(["']).*?\1/gi,"")}function columnStyle(item){return{width:`${item.span/12*100}%`,textAlign:item.align}}function rowStyle(item){return{padding:`${item.padding.top}px ${item.padding.right}px ${item.padding.bottom}px ${item.padding.left}px`}}
